/* Public explanation scope only. Private source identities stay outside this repository. */
const notes={
 5:['snow','적설·융설','Snow processes','경사·D8 흐름방향·시간대는 경험적 융설계수 보정에 반영됩니다. 일사 에너지수지나 적설 이동을 직접 계산하는 방식은 아닙니다.','Slope, D8 flow direction and time of day adjust an empirical melt factor. This is not a direct radiation-energy-balance or snow-transport calculation.'],
 8:['hotstart','HotStart','HotStart','저장 상태에 포함되는 항목은 사용하는 기능에 따라 다를 수 있습니다. 모든 수리 확장의 상태가 동일하게 복원되는 것은 아닙니다.','Saved-state coverage can differ by enabled function; not every hydraulic extension is restored by the same saved state.'],
 10:['subcal','소유역 보정','Subbasin calibration','다지점 보고·진단과 목표지점 보정을 구분합니다. 모든 소유역의 매개변수를 동시에 자동 보정한다는 의미는 아닙니다.','Distinguish multi-site reporting and diagnostics from target-site calibration; this does not imply simultaneous automatic calibration of every subbasin.'],
 13:['multires','1D–2D·다중해상도','1D–2D and multi-resolution','단방향과 양방향 연계는 서로 다른 방식입니다. 관심영역(Patch)은 원지형 해상도를 유지하고 배경 격자를 묶는 방식이며, 입력자료보다 세밀한 지형정보를 새로 만들지는 않습니다.','One-way and two-way coupling are distinct modes. Patches retain source-terrain resolution while background cells are grouped; no terrain detail beyond the input is created.'],
 16:['netcdf','결과·물수지','Outputs and water balance','출력 파일마다 격자와 저장 시각이 다를 수 있습니다. 1D–2D 교환 물수지, 유역 전체 물수지 폐합, 관측자료와의 비교는 서로 다른 평가 항목입니다.','Meshes and output times may differ by file. Exchange balance, watershed closure and observational fit are separate assessments.'],
 17:['estuary','통합 범위','Integration scope','전체 통합 그림은 연구·개발 방향을 포함합니다. D층은 완전한 지하수유동 모형과 다르며, Estuary2DV는 별도 실험 모형입니다.','The integrated overview includes research and development directions. The D-layer is not a complete groundwater solver, and Estuary2DV is a separate experimental model.']
};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function cardNote(id,lang){const n=notes[id];if(!n)return '';const ko=lang==='ko';return `<p class="media-review-note"><strong>${ko?'함께 확인할 내용':'Read with this note'}</strong> ${esc(n[ko?3:4])} <a href="${ko?'ko/':'./'}#cap-${n[0]}">${ko?'기능 설명':'Capability details'} →</a></p>`;}
function review(lang){const ko=lang==='ko';return `<section class="note content-review" data-language="${lang}" ${ko?'':'hidden'}><h2>${ko?'소개자료 안내':'About the introduction materials'}</h2><p>${ko?'2026-09-20 · 소개자료 일부 표현은 현재 홈페이지의 기능 설명이나 적용 범위와 다를 수 있어, 아래 6개 항목에 함께 확인할 내용을 정리했습니다. PDF·영상·이미지는 당시 제작본을 그대로 보존합니다.':'2026-09-20 · A few expressions in the introduction materials may differ from the current website descriptions or scope. Notes for six items are provided below. The original PDF, video and images are preserved.'}</p><details><summary>${ko?'6개 항목의 안내 보기':'Read notes for six items'}</summary>${Object.entries(notes).map(([id,n])=>`<h3>${esc(n[ko?1:2])}</h3>${cardNote(id,lang)}`).join('')}</details></section>`;}
module.exports={notes,cardNote,review};
